/**
 * Baseline schema.
 *
 * Deliberately idempotent — this has to be a no-op against databases created
 * before migrations existed, which already carry every table below. That is why
 * it is a .js migration rather than plain SQL: adding the late columns needs a
 * conditional ALTER, which SQL alone can't express.
 *
 * Do not edit this file. Add a higher-numbered migration instead.
 */
export function up(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS meta (
      key   TEXT PRIMARY KEY,
      value TEXT
    );

    -- One row per browser login. The cookie carries only this row's id, so a
    -- session can be revoked without rotating the signing secret.
    CREATE TABLE IF NOT EXISTS sessions (
      id            TEXT PRIMARY KEY,
      created_at    INTEGER NOT NULL,
      last_seen_at  INTEGER NOT NULL,
      expires_at    INTEGER NOT NULL,
      user_agent    TEXT,
      ip            TEXT,
      label         TEXT,
      revoked_at    INTEGER
    );
    CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);

    -- Keyed by the stable Signal ACI (uuid) when known, otherwise by E.164.
    CREATE TABLE IF NOT EXISTS contacts (
      id            TEXT PRIMARY KEY,
      uuid          TEXT UNIQUE,
      number        TEXT,
      name          TEXT,
      profile_name  TEXT,
      username      TEXT,
      has_avatar    INTEGER NOT NULL DEFAULT 0,
      avatar_etag   TEXT,
      blocked       INTEGER NOT NULL DEFAULT 0,
      updated_at    INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS contacts_number ON contacts(number);

    CREATE TABLE IF NOT EXISTS conversations (
      id            TEXT PRIMARY KEY,          -- dm:<uuid|e164> | group:<internalId>
      type          TEXT NOT NULL,             -- 'dm' | 'group' | 'self'
      name          TEXT,
      contact_id    TEXT,
      group_id      TEXT,                      -- signal-cli "group.xxx" send id
      group_internal_id TEXT,                  -- base64 id seen in envelopes
      members       TEXT,
      description   TEXT,
      has_avatar    INTEGER NOT NULL DEFAULT 0,
      expiration    INTEGER NOT NULL DEFAULT 0,
      muted         INTEGER NOT NULL DEFAULT 0,
      archived      INTEGER NOT NULL DEFAULT 0,
      unread        INTEGER NOT NULL DEFAULT 0,
      last_activity INTEGER NOT NULL DEFAULT 0,
      last_read_ts  INTEGER NOT NULL DEFAULT 0,
      draft         TEXT,
      updated_at    INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS conversations_activity ON conversations(last_activity DESC);
    CREATE INDEX IF NOT EXISTS conversations_internal ON conversations(group_internal_id);

    CREATE TABLE IF NOT EXISTS messages (
      id            INTEGER PRIMARY KEY AUTOINCREMENT,
      conversation_id TEXT NOT NULL,
      ts            INTEGER NOT NULL,          -- Signal sent-timestamp: message identity
      server_ts     INTEGER,
      received_at   INTEGER NOT NULL,
      direction     TEXT NOT NULL,             -- 'in' | 'out'
      author_id     TEXT,
      author_name   TEXT,
      body          TEXT,
      attachments   TEXT,
      quote         TEXT,
      mentions      TEXT,
      sticker       TEXT,
      previews      TEXT,
      text_styles   TEXT,
      kind          TEXT NOT NULL DEFAULT 'message',
      edited_at     INTEGER,
      deleted       INTEGER NOT NULL DEFAULT 0,
      view_once     INTEGER NOT NULL DEFAULT 0,
      expires_in    INTEGER NOT NULL DEFAULT 0,
      status        TEXT NOT NULL DEFAULT '',
      error         TEXT,
      client_id     TEXT,
      UNIQUE(conversation_id, ts, author_id)
    );
    CREATE INDEX IF NOT EXISTS messages_conv_ts ON messages(conversation_id, ts DESC);
    CREATE INDEX IF NOT EXISTS messages_ts ON messages(ts);

    CREATE TABLE IF NOT EXISTS reactions (
      conversation_id TEXT NOT NULL,
      target_ts     INTEGER NOT NULL,
      target_author TEXT NOT NULL,
      author_id     TEXT NOT NULL,
      author_name   TEXT,
      emoji         TEXT NOT NULL,
      ts            INTEGER NOT NULL,
      PRIMARY KEY (conversation_id, target_ts, target_author, author_id)
    );
    CREATE INDEX IF NOT EXISTS reactions_target ON reactions(conversation_id, target_ts);

    -- Local copies of attachments; signal-cli-rest-api prunes its own store.
    CREATE TABLE IF NOT EXISTS attachments (
      id            TEXT PRIMARY KEY,
      content_type  TEXT,
      filename      TEXT,
      size          INTEGER,
      width         INTEGER,
      height        INTEGER,
      local_path    TEXT,
      fetched_at    INTEGER
    );
  `);

  // Columns added after the original schema shipped. Databases created before
  // this migration existed may predate them.
  addColumn(db, 'conversations', 'draft', 'draft TEXT');
  addColumn(db, 'messages', 'client_id', 'client_id TEXT');
}

function addColumn(db, table, column, ddl) {
  const exists = db.prepare(`PRAGMA table_info(${table})`).all().some((c) => c.name === column);
  if (!exists) db.exec(`ALTER TABLE ${table} ADD COLUMN ${ddl}`);
}
